const TEST_SCENARIO_MAPS: Record<PrimaryLang, Record<string, { name: string; description: string }>> = {
  en: EN_TEST_SCENARIOS,
  zh: ZH_TEST_SCENARIOS,
  de: DE_TEST_SCENARIOS,
  fr: FR_TEST_SCENARIOS,
  ja: JA_TEST_SCENARIOS,
};

export function getLocalizedTestScenario<T extends { id: string; name: string; focus: string; description: string }>(
  scenario: T,
  language: LanguageCode
): T {
  if (language === 'it') return scenario;
  const langKey: PrimaryLang = (language in TEST_SCENARIO_MAPS ? language : 'en') as PrimaryLang;
  const textTr = TEST_SCENARIO_MAPS[langKey]?.[scenario.id] || EN_TEST_SCENARIOS[scenario.id];
  const focusMap = FOCUS_TRANSLATIONS[scenario.focus];
  const localizedFocus = focusMap?.[langKey] || focusMap?.en || scenario.focus;

  return {
    ...scenario,
    name: textTr?.name || scenario.name,
    description: textTr?.description || scenario.description,
    focus: localizedFocus,
  };
}
